import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_cuda_src = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row < M && col < N) {
        float val = 0.0;
        for (int i = 0; i < K; i++) {
            val += A[row * K + i] * B[i * N + col];
        }
        C[row * N + col] = val;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are float tensors on CUDA
    TORCH_CHECK(A.device().is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.device().is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat, "A must be a float tensor");
    TORCH_CHECK(B.dtype() == torch::kFloat, "B must be a float tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions must match: A.size(1) == B.size(0)");

    int64_t M = A.size(0);
    int64_t K = A.size(1);
    int64_t N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 block(16, 16);
    dim3 grid((M + block.x - 1) / block.x, (N + block.y - 1) / block.y);

    matmul_kernel<<<grid, block>>>(A.data_ptr<float>(),
                                   B.data_ptr<float>(),
                                   C.data_ptr<float>(),
                                   M, K, N);
    return C;
}
"""

matmul_cpp_decl = r"""
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

# Build the custom CUDA extension
matmul_ext = load_inline(
    name="custom_matmul_ext",
    cpp_sources=matmul_cpp_decl,
    cuda_sources=matmul_cuda_src,
    functions=["matmul_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_func = matmul_ext.matmul_cuda

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul_func(A, B)
